 "content": "def transform(grid):
    # Infer the board's divider color and panel boundaries.
    h, w = len(grid), len(grid[0])
    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    divider_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] != 0 for r in range(h))]
    frame = grid[divider_rows[0]][0] if divider_rows else grid[0][divider_cols[0]]
    divider_rows = [r for r in range(h) if all(v == frame for v in grid[r])]
    divider_cols = [c for c in range(w) if all(grid[r][c] == frame for r in range(h))]
    row_edges = [-1] + divider_rows + [h]
    col_edges = [-1] + divider_cols + [w]
    row_bands = [(row_edges[i] + 1, row_edges[i + 1]) for i in range(len(row_edges) - 1)]
    col_panels = [(col_edges[i] + 1, col_edges[i + 1]) for i in range(len(col_edges) - 1)]
    out = [row[:] for row in grid]

    # Adjacent panels with matching reflected motifs establish a pair. Within
    # each band, complete the missing reflected copy for every established pair.
    pairs = []
    for p in range(len(col_panels) - 1):
        a0, a1 = col_panels[p]
        b0, b1 = col_panels[p + 1]
        if a1 - a0 != b1 - b0:
            continue
        for r0, r1 in row_bands:
            ca = {(r-r0, c-a0, grid[r][c]) for r in range(r0,r1) for c in range(a0,a1) if grid[r][c] not in (0,frame)}
            cb = {(r-r0, b1-1-c, grid[r][c]) for r in range(r0,r1) for c in range(b0,b1) if grid[r][c] not in (0,frame)}
            if ca and ca == cb:
                pairs.append((p,p+1))
                break
    for p,q in pairs:
        a0,a1=col_panels[p]; b0,b1=col_panels[q]
        for r0,r1 in row_bands:
            ca = [(r,c,grid[r][c]) for r in range(r0,r1) for c in range(a0,a1) if grid[r][c] not in (0,frame)]
            cb = [(r,c,grid[r][c]) for r in range(r0,r1) for c in range(b0,b1) if grid[r][c] not in (0,frame)]
            if bool(ca) == bool(cb):
                continue
            if ca:
                for r,c,v in ca:
                    out[r][b0+(a1-1-c)]=v
            else:
                for r,c,v in cb:
                    out[r][a0+(b1-1-c)]=v
    return out
